package Waits {
  component def W {
    attribute ticks: uint = 0;
    attribute ms: uint = 3;
    attribute total: uint = 0;
    operation go() {
      wait 5ns;
      wait 7us;
      wait 2ms;
      wait 3 ms;
      wait 4  us;
      var s: uint = ms * 1000;
      var ns: uint = s + ms;
      var us: uint = ns - 1;
      total = s + ns + us;
      ticks = ticks + 1;
      wait 1s;
      ticks = ticks + 1;
      wait 9007199254740991ns;
    }
    schedule { on start go(); }
  }
  component Demo: W;
}

package Receives {
  port def Ping { provides event p0(n: uint); provides event p1(n: uint); provides event p2(n: uint); provides event p3(n: uint); provides event p4(n: uint); }
  component def Source {
    port out1: Ping;
    operation emit() { wait 3ms; publish out1.p0(7); wait 20ms; publish out1.p2(8); publish out1.p4(9); if (false) { publish out1.p1(1); publish out1.p3(3); } }
    schedule { on start emit(); }
  }
  component def Sink {
    reversed port in1: Ping;
    attribute got: uint = 0;
    attribute timeouts: uint = 0;
    operation listen() {
      on receive in1.p0(n) { got = got + n; } or after 10ms { timeouts = timeouts + 1; }
      on receive in1.p1(n) { got = got + n; } or after 500 us { timeouts = timeouts + 1; }
      on receive in1.p2(n) { got = got + n; } or after 1s { timeouts = timeouts + 1; }
      on receive in1.p3(n) { got = got + n; } or after 9000000ns { timeouts = timeouts + 1; }
      on receive in1.p4(n) { got = got + n; } or after 2 s { timeouts = timeouts + 1; }
    }
    schedule { on start listen(); }
  }
  component def System {
    component src: Source;
    component dst: Sink;
    connect (src.out1, dst.in1);
  }
  component Demo: System;
}

package Timers {
  component def M {
    attribute path: uint = 0;
    attribute s: uint = 0;
    operation run() {
      initial ms;
      state ms {
        on entry { s = s + 1; }
        after 2ms to us { path = path * 10 + 1; }
        after 2000us to ns { path = path * 10 + 9; }
      }
      state us {
        after 30 ms to ns { path = path * 10 + 2; }
        after 20000 us to ns { path = path * 10 + 3; }
      }
      state ns {
        on entry { s = s + 1; }
        after 5ns to done { path = path * 10 + 4; }
      }
      final state done { }
    }
    schedule { on start run(); }
  }
  component Demo: M;
}

package Periods {
  component def P {
    attribute a: uint = 0;
    attribute b: uint = 0;
    attribute c: uint = 0;
    attribute d: uint = 0;
    operation fa() { a = a + 1; }
    operation fb() { b = b + 1; }
    operation fc() { c = c + 1; }
    operation peek() returns uint { return a; }
    operation fe() { var seen: uint = a; }
    operation fd() { d = d + 1; wait 1ms; }
    schedule {
      on every 10ms fa();
      on every 2500 us fb() deadline 2 ms;
      on every 20000000ns fc() deadline 5ms;
      on every 4 ms fe() concurrent;
      on every 1 s fd() deadline 3ms;
    }
  }
  component Demo: P;
}

package Duplicates {
  component def P {
    attribute a: uint = 0;
    operation fa() { a = a + 1; }
    schedule {
      on every 20ms fa();
      on every 20000us fa();
      on every 20000000 ns fa();
    }
  }
  component Demo: P;
}

package Replace {
  component def Base {
    attribute n: uint = 0;
    attribute late: uint = 0;
    operation tick() { n = n + 1; }
    operation slow() { late = late + 1; }
    schedule { on every 20ms tick(); on every 1s slow() deadline 10ms; }
  }
  component def Derived specializes Base {
    schedule { on every 20000us tick() deadline 5ms; on every 1000ms slow(); }
  }
  component Demo: Derived;
}

package Policies {
  import Swaml::Qos;
  qos def Fast: Policy {
    delivery = Delivery.atMostOnce;
    ordering = Ordering.fifo;
    capacity = 4;
    overflow = Overflow.reject;
    requestTimeout = 5ms;
    maxLatency = 2 ms;
    maxAge = 3000us;
  }
  qos def Slow: Policy {
    delivery = Delivery.atLeastOnce;
    ordering = Ordering.unordered;
    capacity = 16;
    overflow = Overflow.dropOldest;
    requestTimeout = 2s;
    maxLatency = 900000000ns;
    maxAge = 1 s;
  }
  port def Api { provides idempotent operation get(k: uint) returns uint; }
  component def Server {
    port api: Api;
    operation serve(k: uint) returns uint { wait 10ms; return k + 1; }
    schedule { on call api.get(k) serve(k); }
  }
  component def Client {
    reversed port api: Api;
    attribute r: uint = 0;
    attribute failed: bool = false;
    operation ask() { r = try(api.get(41), 0); failed = r == 0; }
    schedule { on start ask(); }
  }
  component def Sys {
    component server: Server;
    component client: Client;
    connect c: Fast (client.api, server.api);
  }
  component def Sys2 specializes Sys {
    redefines connect c: Slow (client.api, server.api);
  }
  component Demo: Sys;
  component Demo2: Sys2;
}

package Policies2 {
  import Swaml::Qos;
  qos def Tight: Policy {
    delivery = Delivery.atMostOnce;
    ordering = Ordering.fifo;
    capacity = 1;
    overflow = Overflow.dropNewest;
    requestTimeout = 5 ms;
  }
  port def Api { provides operation get(k: uint) returns uint; }
  component def Server {
    port api: Api;
    operation serve(k: uint) returns uint { wait 10ms; return k + 1; }
    schedule { on call api.get(k) serve(k); }
  }
  component def Client {
    reversed port api: Api;
    attribute r: uint = 0;
    operation ask() { r = try(api.get(41), 7); }
    schedule { on start ask(); }
  }
  component def Sys {
    component server: Server;
    component client: Client;
    connect : Tight (client.api, server.api);
  }
  component Demo: Sys;
}

package BadPolicies {
  import Swaml::Qos;
  qos def A: Policy {
    delivery = Delivery.atMostOnce;
    ordering = Ordering.fifo;
    capacity = 5ms;
    overflow = Overflow.reject;
    requestTimeout = 1s;
  }
  qos def B: Policy {
    delivery = Delivery.atMostOnce;
    ordering = Ordering.fifo;
    capacity = 4;
    overflow = Overflow.reject;
    requestTimeout = 5;
    maxLatency = 5 + 1;
    maxAge = capacity;
  }
  qos def C: Policy {
    delivery = 5ms;
    ordering = 3 s;
    capacity = 4;
    overflow = 1ns;
    requestTimeout = 1s;
    retries = 3ms;
  }
  qos def D: Policy {
    delivery = Delivery.atMostOnce;
    ordering = Ordering.fifo;
    capacity = 4;
    overflow = Overflow.reject;
    requestTimeout = 0ms;
    maxAge = 0 s;
    maxLatency = 9007199254740992ns;
  }
}

package Ranges {
  component def R {
    attribute x: uint = 0;
    operation a() { wait 0ms; }
    operation b() { on receive p.m() { } or after 0ns { } }
    operation c() {
      initial s1;
      state s1 { after 0us to s2 { } }
      final state s2 { }
    }
    operation d() { wait 9007199254740992ns; }
    operation e() { wait 10000000s; }
    port p { provides event m(); }
    schedule {
      on start c();
      on every 0ms a();
      on every 10ms d() deadline 0ms;
      on every 5ms e() deadline 6ms;
      on every 10000000 s b();
    }
  }
  component Demo: R;
}

package UnitNames {
  enum Unit { ns, us, ms, s }
  datatype Span { ms: uint; s: uint; }
  port def Clock { provides event us(ns: uint); }
  component def Holder {
    port clock: Clock;
    attribute ms: uint = 1000;
    attribute s: Unit = Unit.s;
    attribute span: Span = record Span { ms = 5; s = 1; };
    attribute total: uint = 0;
    operation ns(us: uint) returns uint { return us * 1000; }
    operation run() {
      var us: uint = ns(ms);
      total = us + span.ms * span.s;
      if (s == Unit.s) { total = total + 1; }
      wait 1 ms;
      publish clock.us(total);
      wait 1ms;
    }
    schedule { on start run(); }
  }
  component def Ear {
    reversed port clock: Clock;
    attribute heard: uint = 0;
    operation hear(ns: uint) { heard = ns; }
    schedule { on receive clock.us(ns) hear(ns); }
  }
  component def Sys {
    component holder: Holder;
    component ear: Ear;
    connect (holder.clock, ear.clock);
  }
  component Demo: Sys;
}

package Adjacent {
  component def A {
    attribute ms: uint = 2;
    attribute n: uint = 0;
    operation go() {
      while (n < 10, ms times) { n = n + 1; wait 1 ms; }
      wait 2 s;
      n = n + ms;
    }
    schedule { on start go(); }
  }
  component Demo: A;
}

package Scripts {
  port def Bell { provides event ring(n: uint); }
  component def Door {
    port bell: Bell;
    attribute rings: uint = 0;
    operation press() { wait 5ms; rings = rings + 1; publish bell.ring(rings); }
    schedule { on every 20ms press(); }
  }
  component def Visitor { reversed port hear: Bell; }
  component door: Door;
  component visitor: Visitor;
  connect (door.bell, visitor.hear);
  associate visitor to 'Hear the bell';
  test 'Hear the bell' of door {
    wait 1 ms;
    wait 2000us;
    on receive visitor.hear.ring(n) { assert n == 1; } or after 30ms { fail "no ring"; }
    on receive visitor.hear.ring(n) { assert n == 2; } or after 25000000 ns { fail "early timeout"; }
    on receive visitor.hear.ring(n) { fail "no ring expected so soon"; } or after 1ms { }
    wait 30 ms;
    assert door.rings >= 3;
  }
  use case 'Ring' of door {
    wait 25 ms;
    assert true;
  }
}

package Deadlines {
  component def D {
    attribute n: uint = 0;
    operation slow() { n = n + 1; wait 7ms; }
    operation over() { }
    schedule {
      on every 10ms slow() deadline 5 ms;
      on every 10ms over() deadline 11ms;
    }
  }
  component Demo: D;
}

package Deadlines2 {
  component def E {
    attribute n: uint = 0;
    operation slow() { n = n + 1; wait 7ms; }
    schedule { on every 10ms slow() deadline 5 ms; }
  }
  component Run: E;
}

package Stale {
  port def P { provides event m(); }
  component def S {
    reversed port p: P;
    attribute count: uint = 0;
    attribute other: uint = 0;
    operation bump() {
      var n: uint = count;
      wait 1ms;
      count = n + 1;
    }
    operation listen() {
      var n: uint = other;
      on receive p.m() { } or after 5 ms { }
      other = n + 1;
    }
    schedule { on every 10ms bump(); on start listen(); }
  }
  component def T {
    port p: P;
    operation go() { wait 2ms; publish p.m(); }
    schedule { on start go(); }
  }
  component def Sys {
    component s: S;
    component t: T;
    connect (t.p, s.p);
  }
  component Demo: Sys;
}

package Mixed {
  import Swaml::Qos;
  qos def M: Policy {
    delivery = Delivery.atMostOnce;
    ordering = Ordering.fifo;
    capacity = 2 s;
    overflow = Overflow.reject;
    requestTimeout = 100;
    maxLatency = Delivery.atMostOnce;
    maxAge = "1s";
  }
  qos def Mine: Default {
    requestTimeout = 3ms;
  }
  component def U {
    attribute ms: uint = 5;
    operation f() { }
    schedule { on every 5ms f() deadline 6 ms; }
  }
  component Demo: U;
}

package LibraryPolicies {
  import Swaml::Qos;
  qos def Full: Policy {
    delivery = Delivery.bestEffort;
    ordering = Ordering.fifo;
    capacity = 2;
    overflow = Overflow.dropNewest;
    requestTimeout = 3 ms;
    maxAge = 1ms;
  }
  port def Feed { provides event tick(n: uint); }
  component def Pub {
    port feed: Feed;
    operation go() { var i: uint = 0; while (i < 5) { i = i + 1; publish feed.tick(i); } }
    schedule { on start go(); }
  }
  component def Sub {
    reversed port feed: Feed;
    attribute last: uint = 0;
    attribute seen: uint = 0;
    operation take(n: uint) { wait 2ms; last = n; seen = seen + 1; }
    schedule { on receive feed.tick(n) take(n); }
  }
  component def Sys {
    component pub: Pub;
    component sub: Sub;
    connect : Full (pub.feed, sub.feed);
  }
  component Demo: Sys;
}

package Chains {
  component def C {
    attribute order: uint = 0;
    attribute stateTicks: uint = 0;
    operation first() { wait 1ms; order = order * 10 + 1; }
    operation second() { order = order * 10 + 2; }
    operation machine() {
      initial a;
      state a { after 4ms to b { stateTicks = stateTicks + 1; } }
      state b { after 4 ms to a { stateTicks = stateTicks + 1; } }
    }
    schedule {
      on every 10ms first() deadline 2ms;
      after first second();
      on start machine();
    }
  }
  component Demo: C;
}

package Spelling {
  component def S {
    attribute n: uint = 0;
    operation f() { wait 005ms; wait 1 /* unit */ ms; n = n + 1; }
    schedule { on every 0020 ms f() deadline 010ms; }
  }
  component Demo: S;
}

package Redefined {
  component def Worker {
    attribute periodMs: uint = 20;
    const attribute limit: uint = 3;
    attribute n: uint = 0;
    operation tick() { if (n < limit) { n = n + 1; } }
    schedule { on every 20ms tick(); }
  }
  component def Pair {
    component a: Worker;
    component b: Worker;
  }
  component Demo: Pair {
    redefines component b: Worker {
      redefines const attribute limit: uint = 5;
      redefines attribute periodMs: uint = 10;
    }
  }
}

package Entries {
  port def Ctl { provides event stop(); provides event go(n: uint); }
  port def Api { provides operation get() returns uint; }
  component def Worker {
    reversed port ctl: Ctl;
    port api: Api;
    attribute n: uint = 0;
    attribute stopped: bool = false;
    operation work(k: uint) {
      interruptible {
        wait 2ms;
        wait 1 ms;
        n = n + k;
      } on receive ctl.stop() {
        stopped = true;
      }
    }
    operation serve() returns uint { wait 1us; return n; }
    schedule {
      on receive ctl.go(k) work(k) deadline 4 ms;
      on call api.get() serve() deadline 500000ns;
    }
  }
  component def Boss {
    port ctl: Ctl;
    reversed port api: Api;
    attribute seen: uint = 0;
    operation run() { publish ctl.go(3); wait 5ms; publish ctl.go(4); wait 1ms; publish ctl.stop(); wait 5ms; seen = api.get(); }
    schedule { on start run(); }
  }
  component def Sys {
    component worker: Worker;
    component boss: Boss;
    connect (boss.ctl, worker.ctl);
    connect (boss.api, worker.api);
  }
  component Demo: Sys;
}
